1	import { test } from 'node:test';
2	import assert from 'node:assert/strict';
3	import {
4	  normalizeDelivery, resolveDelivery, DEFAULT_DELIVERY, pendingAgentic, heldStamp,
5	  maintenanceBranchName, openMaintenanceBranch, openMaintenancePull, shouldRequestAgent,
6	  unconfiguredSecrets, SECRETS_ISSUE_TITLE, workflowTriggers, ciDispatchPlan,
7	  pullCreateError, deliveryAction,
8	} from '../../packs/basics/tasks/baselining/worker.mjs';
9	
10	// The worker's PURE decision helpers (agent-preprocessing DESIGN §7, E4). The
11	// native-git / clone / REST I/O in main() is validated by the live pilot; these
12	// are the git-free unit surface.
13	
14	test('normalizeDelivery maps the accepted values and legacy aliases, rejecting the rest', () => {
15	  assert.equal(normalizeDelivery('auto-merge'), 'auto-merge');
16	  assert.equal(normalizeDelivery('auto'), 'auto-merge');   // legacy alias
17	  assert.equal(normalizeDelivery('push'), 'auto-merge');   // legacy alias
18	  assert.equal(normalizeDelivery('review'), 'review');
19	  assert.equal(normalizeDelivery('pr'), 'review');         // legacy alias
20	  assert.equal(normalizeDelivery(' review '), 'review');   // trimmed
21	  assert.equal(normalizeDelivery('bogus'), null);
22	  assert.equal(normalizeDelivery(undefined), null);
23	});
24	
25	// A MISSING maintenance.delivery is drift, not an error: the only writer is
26	// check_the_world --init (first adoption), so a repo adopted before the key existed
27	// — or one whose key was hand-removed — has nothing that could ever put it back,
28	// and a hard failure would just fail baselining every night forever. Materialize
29	// the default instead. An UNRECOGNIZED value stays a hard failure: substituting a
30	// default there would deliver the opposite of a stated intent.
31	test('resolveDelivery materializes the default for a missing key rather than failing the run', () => {
32	  assert.deepEqual(resolveDelivery(undefined), { delivery: DEFAULT_DELIVERY, materialize: true });
33	  assert.deepEqual(resolveDelivery(null), { delivery: DEFAULT_DELIVERY, materialize: true });
34	  assert.equal(DEFAULT_DELIVERY, 'auto-merge');
35	});
