42	    return { name, ok: false, stdout: `${e.stdout ?? ''}${e.stderr ?? ''}`.trim() || e.message };
43	  }
44	}
45	
46	export function buildFixture(fixture, mode) {
47	  const root = mkdtempSync(join(tmpdir(), `claudinite-rehearsal-${fixture.name}-`));
48	  for (const [rel, content] of Object.entries(fixture.files)) {
49	    const abs = join(root, rel);
50	    mkdirSync(dirname(abs), { recursive: true });
51	    // The declaration carries the mode's stamp — that is what selects migration notes.
52	    writeFileSync(abs, rel === '.claudinite-checks.json'
53	      ? content.replace('"updated": null', `"updated": ${JSON.stringify(mode.updated)}`)
54	      : content);
55	  }
56	  // A real repo, because the sweep scopes its file set with git and an
57	  // uninitialised directory makes it fall back to whatever cwd it can find.
58	  const git = (...a) => execFileSync('git', a, { cwd: root, stdio: 'ignore' });
59	  git('init', '-q', '-b', 'main');
60	  git('-c', 'user.email=rehearsal@example.invalid', '-c', 'user.name=rehearsal',
61	    'commit', '-q', '--allow-empty', '-m', 'fixture');
62	  git('add', '-A');
63	  git('-c', 'user.email=rehearsal@example.invalid', '-c', 'user.name=rehearsal',
64	    'commit', '-q', '-m', 'fixture content');
65	  return root;
66	}
67	
68	export function rehearse(fixture, mode) {
69	  const root = buildFixture(fixture, mode);
70	  const steps = [];
71	  try {
72	    // apply-vendor-set reads the CANON checkout (its own root), so it alone runs
73	    // with the canon as cwd. Everything after it judges the FIXTURE, and must run
74	    // with the fixture as cwd — a sweep inheriting the canon's cwd resolves git
75	    // against the canon and cheerfully reports on the wrong repo.
76	    steps.push(step('apply-vendor-set', [join(CANON, 'vendoring/apply-vendor-set.mjs'), '--target', root]));
77	    if (steps.at(-1).ok) {
78	      steps.push(step('converge-wiring', [join(CANON, 'engine/scheduler/converge-wiring.mjs'), 'fixture/rehearsal'],
79	        { CLAUDINITE_REPO_ROOT: root }, root));
80	      steps.push(step('migrations-apply', [join(CANON, 'migrations/apply.mjs')], { CLAUDE_PROJECT_DIR: root }, root));
81	      steps.push(step('selftest', [join(CANON, 'engine/selftest.mjs'), '--strict'], { CLAUDE_PROJECT_DIR: root }, root));
82	      const sweep = join(root, '.claudinite/shared/engine/checks/check_the_world.mjs');
83	      // The member runs its own VENDORED sweep, not the canon's — that is the
84	      // copy it will actually live with, and a converge that failed to vendor it
85	      // must read as a failure here rather than be silently covered for.
86	      steps.push(existsSync(sweep)
87	        ? step('check-the-world', [sweep], { CLAUDE_PROJECT_DIR: root }, root)
88	        : { name: 'check-the-world', ok: false, stdout: 'the converge vendored no check_the_world.mjs' });
89	    }
90	    const stamp = existsSync(join(root, '.claudinite-checks.json'))
91	      ? JSON.parse(readFileSync(join(root, '.claudinite-checks.json'), 'utf8')).claudinite
92	      : null;
93	    const failed = steps.filter((s) => !s.ok);
94	    return { fixture: fixture.name, mode: mode.name, ok: failed.length === 0, steps, failed, stamp };
95	  } finally {
96	    rmSync(root, { recursive: true, force: true });
97	  }
98	}
99	
100	// A one-line verdict per (fixture, mode), and the failing step's output beneath
101	// it — the shape a CI log should have when a canon PR breaks the fleet.
102	export function formatResult(r) {
103	  const head = `${r.ok ? 'PASS' : 'FAIL'}  ${r.fixture} [${r.mode}]`;
104	  if (r.ok) return head;
105	  return [head, ...r.failed.map((f) => `  ${f.name}:\n${f.stdout.split('\n').map((l) => `    ${l}`).join('\n')}`)].join('\n');
106	}

