51	    out.push({ file: STUB, what: 'the scheduler workflow stub — every member vendors it verbatim' });
52	  }
53	  for (const file of changed) {
54	    // A rule module whose severity line changed. Read the current text: a rule
55	    // that now says `blocking` in a changed file is the case worth asking about,
56	    // and the direction that matters (advisory -> blocking) is the one that turns
57	    // a green member red without the member changing at all.
