1	// The baselining REHEARSAL runner (#593 phase 2): build a fixture consumer in a
2	// temp dir, run the REAL converge against this canon checkout, and report what a
3	// member would be left with.
4	//
5	// "The real converge" is load-bearing. It invokes the same three scripts the
6	// nightly worker invokes, as subprocesses, in the same order:
7	//
8	//   vendoring/apply-vendor-set.mjs   the mount + stamp
9	//   engine/scheduler/converge-wiring.mjs   workflow, hooks, badge row
10	//   migrations/apply.mjs             the mechanical notes
11	//
12	// then asks the two questions that matter, in the order that matters:
13	//
14	//   engine/selftest.mjs      can Claudinite still RUN here?
15	//   check_the_world.mjs      and is the result conformant?
16	//
17	// Self-test first, because it is the one that catches a machinery break — and a
18	// broken machine reports no findings precisely because it is not running, so a
19	// content check consulted first would answer "green" and mean nothing.
20	//
21	// A rehearsal never touches the canon and never touches a real repo: everything
22	// happens under a temp dir that is removed afterwards.
23	
24	import { mkdtempSync, mkdirSync, writeFileSync, rmSync, existsSync, readFileSync } from 'node:fs';
25	import { execFileSync } from 'node:child_process';
26	import { join, dirname } from 'node:path';
27	import { tmpdir } from 'node:os';
28	import { fileURLToPath } from 'node:url';
29	
30	export const CANON = dirname(dirname(dirname(fileURLToPath(import.meta.url)))); // packs-tests/rehearsal -> canon
31	
32	// Every step is captured, never thrown: a rehearsal that dies on step two must
33	// still report which step and why, because "it failed" is not actionable and
34	// "apply-vendor-set exited 1 saying X" is.
35	function step(name, argv, env = {}, cwd = undefined) {
36	  try {
37	    const stdout = execFileSync(process.execPath, argv, {
38	      encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], env: { ...process.env, ...env }, cwd,
39	    });
40	    return { name, ok: true, stdout };
41	  } catch (e) {
42	    return { name, ok: false, stdout: `${e.stdout ?? ''}${e.stderr ?? ''}`.trim() || e.message };
