48	  for (const [rel, content] of Object.entries(fixture.files)) {
49	    const abs = join(root, rel);
50	    mkdirSync(dirname(abs), { recursive: true });
51	    // The declaration carries the mode's stamp — that is what selects migration notes.
52	    writeFileSync(abs, rel === '.claudinite-checks.json'
53	      ? content.replace('"updated": null', `"updated": ${JSON.stringify(mode.updated)}`)
54	      : content);
55	  }
56	  // A real repo, because the sweep scopes its file set with git and an
57	  // uninitialised directory makes it fall back to whatever cwd it can find.
58	  //
59	  // `--no-gpg-sign` and the inline identity are not tidiness: a fixture must not
60	  // depend on the HOST's git configuration. A machine with commit signing wired
61	  // up fails these commits for reasons that have nothing to do with the canon
62	  // change under test, and the rehearsal then reports a fleet-breaking result
63	  // because a signing helper was unavailable.
64	  const git = (...a) => execFileSync('git', [
65	    '-c', 'user.email=rehearsal@example.invalid', '-c', 'user.name=rehearsal',
66	    '-c', 'commit.gpgsign=false', '-c', 'gpg.format=openpgp', ...a,
67	  ], { cwd: root, stdio: 'ignore' });
68	  git('init', '-q', '-b', 'main');
69	  git('commit', '-q', '--allow-empty', '--no-gpg-sign', '-m', 'fixture');
70	  git('add', '-A');
71	  git('commit', '-q', '--no-gpg-sign', '-m', 'fixture content');
72	  return root;
73	}
