75	export function rehearse(fixture, mode) {
76	  const root = buildFixture(fixture, mode);
77	  const steps = [];
78	  try {
79	    // apply-vendor-set reads the CANON checkout (its own root), so it alone runs
80	    // with the canon as cwd. Everything after it judges the FIXTURE, and must run
81	    // with the fixture as cwd — a sweep inheriting the canon's cwd resolves git
82	    // against the canon and cheerfully reports on the wrong repo.
83	    steps.push(step('apply-vendor-set', [join(CANON, 'vendoring/apply-vendor-set.mjs'), '--target', root]));
84	    if (steps.at(-1).ok) {
85	      steps.push(step('converge-wiring', [join(CANON, 'engine/scheduler/converge-wiring.mjs'), 'fixture/rehearsal'],
86	        { CLAUDINITE_REPO_ROOT: root }, root));
87	      steps.push(step('migrations-apply', [join(CANON, 'migrations/apply.mjs')], { CLAUDE_PROJECT_DIR: root }, root));
88	      steps.push(step('selftest', [join(CANON, 'engine/selftest.mjs'), '--strict'], { CLAUDE_PROJECT_DIR: root }, root));
89	      const sweep = join(root, '.claudinite/shared/engine/checks/check_the_world.mjs');
90	      // The member runs its own VENDORED sweep, not the canon's — that is the
91	      // copy it will actually live with, and a converge that failed to vendor it
92	      // must read as a failure here rather than be silently covered for.
93	      steps.push(existsSync(sweep)
94	        ? step('check-the-world', [sweep], { CLAUDE_PROJECT_DIR: root }, root)
95	        : { name: 'check-the-world', ok: false, stdout: 'the converge vendored no check_the_world.mjs' });
96	    }
97	    const stamp = existsSync(join(root, '.claudinite-checks.json'))
98	      ? JSON.parse(readFileSync(join(root, '.claudinite-checks.json'), 'utf8')).claudinite
99	      : null;
100	    const failed = steps.filter((s) => !s.ok);
101	    return { fixture: fixture.name, mode: mode.name, ok: failed.length === 0, steps, failed, stamp };
102	  } finally {
103	    rmSync(root, { recursive: true, force: true });
104	  }
105	}
